spec.expr:
histogram_quantile(
  0.95,
  sum by (le, operation) (
    rate(
      mexe_processing_duration_seconds_bucket{
        stage="final"
      }[5m]
    )
  )
)

histogram_quantile(
  0.95,
  sum by (le, operation, stage) (
    rate(
      mexe_processing_duration_seconds_bucket{
        stage!="final"
      }[5m]
    )
  )
)
